 "content": "from collections import Counter


def transform(grid):
    """Color short background gaps between matching markers along rows/columns."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    markers = [value for value in counts if value != background]
    if not markers:
        return [row[:] for row in grid]
    marker = max(markers, key=lambda value: counts[value])
    out = [row[:] for row in grid]

    # Only recolor bounded gaps of at most six background cells.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != background:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] == background:
                c += 1
            if (c - start <= 6 and start > 0 and c < w
                    and grid[r][start - 1] == marker and grid[r][c] == marker):
                for x in range(start, c):
                    out[r][x] = 2

    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != background:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] == background:
                r += 1
            if (r - start <= 6 and start > 0 and r < h
                    and grid[start - 1][c] == marker and grid[r][c] == marker):
                for y in range(start, r):
                    out[y][c] = 2

    return out
