 "content": "from collections import Counter


def transform(grid):
    """Fill short runs of the background between equal colored markers."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    marker = max((value for value in counts if value != background), key=lambda v: counts[v])
    out = [row[:] for row in grid]

    # Color background gaps of length 1..6 bracketed by markers.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background:
                continue
            end = c
            while end < w and grid[r][end] == background:
                end += 1
            if (1 <= end - c <= 6 and c > 0 and end < w
                    and grid[r][c - 1] == marker and grid[r][end] == marker):
                for x in range(c, end):
                    out[r][x] = 2
                c = end - 1

    for c in range(w):
        for r in range(h):
            if grid[r][c] != background:
                continue
            end = r
            while end < h and grid[end][c] == background:
                end += 1
            if (1 <= end - r <= 6 and r > 0 and end < h
                    and grid[r - 1][c] == marker and grid[end][c] == marker):
                for y in range(r, end):
                    out[y][c] = 2
                r = end - 1

    return out
