 "content": "from collections import Counter


def transform(grid):
    """Color 2 in gaps between adjacent occurrences of the sparse color."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    marker = min((value for value in counts if value != background), key=lambda v: counts[v])
    out = [row[:] for row in grid]

    # Vertical connections join repeated markers in the same column.
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        for top, bottom in zip(positions, positions[1:]):
            for r in range(top + 1, bottom):
                if grid[r][c] == background:
                    out[r][c] = 2

    # Horizontal connections fill narrow marker gaps, not large separations.
    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == marker]
        for left, right in zip(positions, positions[1:]):
            if right - left <= 4:
                for c in range(left + 1, right):
                    if grid[r][c] == background:
                        out[r][c] = 2

    return out
