 "content": "from collections import Counter


def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = min((v for v in counts if v != background), key=lambda v: counts[v])
    out = [row[:] for row in grid]

    # Gaps of up to six cells between consecutive markers are colored 2.
    max_separation = 7
    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == marker]
        for left, right in zip(positions, positions[1:]):
            if right - left <= max_separation:
                for c in range(left + 1, right):
                    if grid[r][c] == background:
                        out[r][c] = 2

    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        for top, bottom in zip(positions, positions[1:]):
            if bottom - top <= max_separation:
                for r in range(top + 1, bottom):
                    if grid[r][c] == background:
                        out[r][c] = 2

    return out
